function isInTradingSession(symbol: string, hourUTC: number): boolean {
  // Normalize: strip broker suffixes (.raw, .c, .pro, .m, #, .i, etc.) and slashes
  const raw = symbol.toUpperCase().replace('/', '').replace(/[#.]/g, '').replace(/(RAW|PRO|C|M|I|SB|ECN|MT5)$/, '');
  // Map known aliases to canonical symbols
  const ALIAS_MAP: Record<string, string> = {
    // Gold variants
    'GOLD': 'XAUUSD', 'GOLDM': 'XAUUSD', 'GOLDC': 'XAUUSD', 'GOLDPRO': 'XAUUSD',
    'XAUC': 'XAUUSD', 'XAUI': 'XAUUSD', 'XAUUSDC': 'XAUUSD', 'XAUUSDRAW': 'XAUUSD',
    // US30 / Dow Jones variants
    'WS30': 'US30', 'DJIA': 'US30', 'DJI': 'US30', 'DOW': 'US30',
    'DOW30': 'US30', 'DOWJONES': 'US30', 'USA30': 'US30', 'CASH30': 'US30',
    'DJA': 'US30', 'WALLST30': 'US30', 'WALLSTREET30': 'US30', 'USWALL': 'US30',
    'US30CASH': 'US30', 'US30C': 'US30', 'US30USD': 'US30', 'YM': 'US30',
    // NAS100 / Nasdaq variants
    'USTEC': 'NAS100', 'NASDAQ100': 'NAS100', 'NDX100': 'NAS100',
    'NASDAQ': 'NAS100', 'NQ': 'NAS100', 'QQQ': 'NAS100', 'NDAQ': 'NAS100',
    'NA100': 'NAS100', 'NASUSD': 'NAS100', 'TECH100': 'NAS100',
    'USTECH100': 'NAS100', 'NASD100': 'NAS100', 'NAS100USD': 'NAS100',
    'NAS100CASH': 'NAS100', 'NAS100C': 'NAS100', 'US100': 'NAS100',
    // S&P 500 variants
    'SP500USD': 'SPX500', 'SPXUSD': 'SPX500', 'ES': 'SPX500',
    'SPX': 'SPX500', 'SPXC': 'SPX500', 'SP500C': 'SPX500', 'SPXUSDM': 'SPX500',
    'US500CASH': 'US500', 'USINDEX': 'SPX500', 'SPX500USD': 'SPX500',
  };
  const sym = ALIAS_MAP[raw] ?? raw;
  const windows = PAIR_SESSION_WINDOWS[sym];
  if (!windows) {
    // Partial match fallback: find first key that starts with or contains sym
    const fallback = Object.keys(PAIR_SESSION_WINDOWS).find(k => k.startsWith(sym) || sym.startsWith(k));
    if (fallback) return PAIR_SESSION_WINDOWS[fallback].some(([s, e]) => hourUTC >= s && hourUTC < e);
    return true; // unknown symbol — don't block
  }
  return windows.some(([start, end]) => hourUTC >= start && hourUTC < end);
}

function tlSignalGuard(params: {
  confidence?: number;
  entryPrice?: number | null;
  stopLoss?: number | null;
  takeProfit?: number | null;
  symbol?: string;
  direction?: string;
  riskScore?: number | null;
  minConfidence?: number;
  requireSLTP?: boolean;
  checkSession?: boolean;
  /** Override minimum R:R — pass 1.5 for ranging/tight-range conditions */
  minRR?: number;
}): { allow: boolean; reason: string } {
  const {
    confidence = 0,
    entryPrice,
    stopLoss,
    takeProfit,
    minConfidence = 70,
    requireSLTP = true,
    checkSession = false,
    riskScore,
    minRR,
  } = params;
  const sym = params.symbol || '';
  const dir = (params.direction || '').toUpperCase();

  // 1. Confidence gate
  if (confidence < minConfidence) {
    return { allow: false, reason: `Confidence ${confidence}% below ${minConfidence}% minimum — blocked` };
  }

  // 2. Stop loss required — no SL = undefined risk
  if (requireSLTP && (!stopLoss || stopLoss <= 0)) {
    return { allow: false, reason: `No stop loss on ${sym} — undefined risk, blocked` };
  }

  // 3. Take profit required
  if (requireSLTP && (!takeProfit || takeProfit <= 0)) {
    return { allow: false, reason: `No take profit on ${sym} — no exit target, blocked` };
  }

  if (entryPrice && entryPrice > 0 && stopLoss && stopLoss > 0 && takeProfit && takeProfit > 0) {
    // 4. Direction sanity — SL/TP must be on the correct side of entry
    if (dir === 'BUY') {
      if (stopLoss >= entryPrice) {
        return { allow: false, reason: `BUY ${sym}: SL ${stopLoss} >= entry ${entryPrice} — inverted levels, blocked` };
      }
      if (takeProfit <= entryPrice) {
        return { allow: false, reason: `BUY ${sym}: TP ${takeProfit} <= entry ${entryPrice} — inverted levels, blocked` };
      }
    } else if (dir === 'SELL') {
      if (stopLoss <= entryPrice) {
        return { allow: false, reason: `SELL ${sym}: SL ${stopLoss} <= entry ${entryPrice} — inverted levels, blocked` };
      }
      if (takeProfit >= entryPrice) {
        return { allow: false, reason: `SELL ${sym}: TP ${takeProfit} >= entry ${entryPrice} — inverted levels, blocked` };
      }
    }

    // 5. Dynamic R:R gate
    // Default 2.0; auto-relax to 1.5 when SL is tight (< 0.15% of price = ranging/compressed
    // conditions). Caller can also explicitly pass minRR to override.
    const riskDist = Math.abs(entryPrice - stopLoss);
    const rewardDist = Math.abs(takeProfit - entryPrice);
    if (riskDist > 0) {
      const rr = rewardDist / riskDist;
      const slPct = riskDist / entryPrice;
      // Auto-detect tight range: SL is < 0.15% of price (Forex) or < 0.3% (crypto/commodities)
      const isCryptoOrComm = ['BTC','ETH','XAU','GOLD','OIL','SILVER'].some(t => sym.toUpperCase().includes(t));
      const tightRangeThreshold = isCryptoOrComm ? 0.003 : 0.0015;
      const effectiveMinRR = minRR !== undefined ? minRR
        : (slPct < tightRangeThreshold ? 1.5 : 2.0);
      if (rr < effectiveMinRR) {
        return { allow: false, reason: `R:R ${rr.toFixed(2)} on ${sym} ${dir} below ${effectiveMinRR.toFixed(1)} minimum${slPct < tightRangeThreshold ? ' (ranging market)' : ''} — blocked` };
      }
    }
  }

  // 6. Risk score gate — block signals the AI itself rated as high risk
  if (riskScore != null && riskScore > 7) {
    return { allow: false, reason: `AI risk score ${riskScore}/10 on ${sym} exceeds max 7 — blocked` };
  }

  // 7. News event window gate — tighten filtering during historically high-volatility news hours
  // High-impact windows (UTC): Tue 13-15 (CPI/Retail), Wed 13-15 & 17-20 (FOMC/ADP), Thu 11-14 (ECB/Claims), Fri 13-15 (NFP)
  const nowForNews = new Date();
  const dayUTC = nowForNews.getUTCDay(); // 0=Sun
  const hourUTC_news = nowForNews.getUTCHours();
  const HIGH_IMPACT_WINDOWS: Record<number, number[]> = {
    2: [13, 14, 15],       // Tuesday
    3: [13, 14, 17, 18, 19], // Wednesday
    4: [11, 12, 13, 14],   // Thursday
    5: [13, 14, 15],       // Friday (NFP)
  };
  const isNewsWindow = HIGH_IMPACT_WINDOWS[dayUTC]?.includes(hourUTC_news) ?? false;
  if (isNewsWindow && riskScore != null && riskScore > 6) {
    return { allow: false, reason: `Risk score ${riskScore} during high-impact news window (${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][dayUTC]} ${hourUTC_news}:00 UTC) — threshold tightened to 6 — blocked` };
  }

  // 8. Session filter — block trades outside the instrument's liquidity window
  if (checkSession) {
    const hourUTC = new Date().getUTCHours();
    if (!isInTradingSession(sym, hourUTC)) {
      return { allow: false, reason: `${sym} outside its best session at ${hourUTC}:00 UTC — low liquidity, blocked` };
    }
  }

  return { allow: true, reason: 'Passed all signal quality gates' };
}
