  app.post("/api/tradelocker/connection", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ error: "Authentication required" });
    }
    const userId = (req.user as User).id;

    const { email, password, serverId, accountId, accountType, autoExecute } = req.body;

    if (!email || !password || !serverId || !accountId) {
      return res.status(400).json({ error: "Missing required fields: email, password, serverId, accountId" });
    }

    // Test connection FIRST — authenticate before encrypting anything
    let resolvedAccNum: string | undefined;
    try {
      const service = new TradeLockerService(accountType || 'live', accountId, serverId);
      await service.authenticate(email, password);
      const accNum = service.getResolvedAccNum();
      if (accNum && accNum !== '0') resolvedAccNum = accNum;
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Unknown error';
      return res.status(400).json({ error: `TradeLocker login failed: ${msg}` });
    }

    // Encrypt password after successful auth
    const encryptedPw = encryptPassword(password);
    
    const connection = await storage.createTradelockerConnection({
      userId,
      email,
      encryptedPassword: encryptedPw,
      serverId,
      accountId,
      accountType: accountType || 'live',
      isActive: true,
      autoExecute: autoExecute || false,
      ...(resolvedAccNum ? { accNum: resolvedAccNum } : {}),
    });
    
    // Persist accNum and lastConnectedAt immediately
    if (resolvedAccNum) {
      await storage.updateTradelockerConnection(connection.id, {
        accNum: resolvedAccNum,
        lastConnectedAt: new Date(),
        lastError: null,
      });
    }
    
    const { encryptedPassword: _, ...safeConnection } = connection;
    res.json({ ...safeConnection, accNum: resolvedAccNum || null });
  });

  // PATCH by ID — update a specific connection (multi-account)
  app.patch("/api/tradelocker/connection/:id", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ error: "Authentication required" });
    }
    const userId = (req.user as User).id;
    const connId = parseInt(req.params.id, 10);

    const connection = await storage.getTradelockerConnection(connId);
    if (!connection || connection.userId !== userId) {
      return res.status(404).json({ error: "No connection found" });
    }

    const { isActive, autoExecute, lotMultiplier, gateMode, useRiskPercent, riskPercent } = req.body;
    const updateDataById: Record<string, any> = {};
    if (isActive !== undefined) updateDataById.isActive = isActive;
    if (autoExecute !== undefined) updateDataById.autoExecute = autoExecute;
    if (lotMultiplier !== undefined) {
      const mult = parseFloat(lotMultiplier);
      if (!isNaN(mult) && mult >= 0.01 && mult <= 10) updateDataById.lotMultiplier = mult;
    }
    if (gateMode !== undefined && (gateMode === 'full' || gateMode === 'basic')) {
      updateDataById.gateMode = gateMode;
    }

    // Per-account risk-% sizing (stored in JSON sidecar — no DB column)
    if (useRiskPercent !== undefined || riskPercent !== undefined) {
      const { setTLRisk } = await import('./services/tl-risk-settings');
      const patch: any = {};
      if (useRiskPercent !== undefined) patch.useRiskPercent = !!useRiskPercent;
      if (riskPercent !== undefined) { const r = parseFloat(riskPercent); if (!isNaN(r)) patch.riskPercent = r; }
      setTLRisk(connId, patch);
    }

    // updateTradelockerConnection requires at least one DB field; skip if only risk changed
    let updated = await storage.getTradelockerConnection(connId);
    if (Object.keys(updateDataById).length > 0) {
      updated = await storage.updateTradelockerConnection(connId, updateDataById);
    }
    if (!updated) {
      return res.status(500).json({ error: "Failed to update connection" });
    }

    const { getTLRisk } = await import('./services/tl-risk-settings');
    const { encryptedPassword: _, accessToken, refreshToken, ...safeConnection } = updated;
    res.json({ ...safeConnection, ...getTLRisk(connId) });
  });

