      if (status === 'live') {
        updateData.liveStartedAt = new Date();
      } else if (status === 'completed') {
        updateData.liveEndedAt = new Date();
      }
      
      const updated = await storage.updateEventSchedule(scheduleId, updateData);
      
      res.json({ success: true, schedule: updated });
