  app.post("/api/user-api-keys", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: "Not authenticated" });
    try {
      const { provider, apiKey, label } = req.body;
      const validProviders = ['openai', 'anthropic', 'google', 'groq', 'mistral', 'elevenlabs'];
      if (!validProviders.includes(provider)) {
        return res.status(400).json({ message: "Invalid provider. Must be one of: " + validProviders.join(', ') });
      }
      if (!apiKey || typeof apiKey !== 'string' || apiKey.trim().length < 10) {
        return res.status(400).json({ message: "Invalid API key" });
      }

      const existingKeys = await storage.getUserApiKeys(req.user!.id);
      const isUpdating = existingKeys.some(k => k.provider === provider);
      if (!isUpdating && existingKeys.length >= 5) {
        return res.status(400).json({ message: "Maximum of 5 AI providers allowed" });
      }

      const result = await storage.createOrUpdateUserApiKey({
        userId: req.user!.id,
        provider,
        apiKey: apiKey.trim(),
        label: label || provider,
        isActive: true,
        isValid: null,
      });

      // Auto-validate immediately after saving so the engine knows if it works
      let isValid: boolean | null = null;
      try {
        const trimmedKey = apiKey.trim();
        if (provider === 'openai') {
          const testClient = new (await import('openai')).default({ apiKey: trimmedKey });
          await testClient.models.list();
          isValid = true;
        } else if (provider === 'anthropic') {
          const resp = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: { 'x-api-key': trimmedKey, 'content-type': 'application/json', 'anthropic-version': '2023-06-01' },
            body: JSON.stringify({ model: 'claude-3-haiku-20240307', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] }),
          });
          isValid = resp.status !== 401 && resp.status !== 403;
        } else if (provider === 'google') {
          const resp = await fetch(`https://generativelanguage.googleapis.com/v1/models?key=${trimmedKey}`);
          isValid = resp.ok;
        } else if (provider === 'groq') {
          const resp = await fetch('https://api.groq.com/openai/v1/models', { headers: { 'Authorization': `Bearer ${trimmedKey}` } });
          isValid = resp.ok;
        } else if (provider === 'mistral') {
          const resp = await fetch('https://api.mistral.ai/v1/models', { headers: { 'Authorization': `Bearer ${trimmedKey}` } });
          isValid = resp.ok;
        } else if (provider === 'elevenlabs') {
          // /v1/models is the most reliable auth check — returns 200 for any valid key,
          // 401 for invalid. Avoids the 422/plan-tier issues that /v1/user can return.
          try {
            const r = await fetch('https://api.elevenlabs.io/v1/models', { headers: { 'xi-api-key': trimmedKey } });
            isValid = r.ok;
            if (!r.ok && r.status !== 401 && r.status !== 403) {
              // Non-auth error (network, 500, etc.) — fall back to voices list
              const r2 = await fetch('https://api.elevenlabs.io/v1/voices', { headers: { 'xi-api-key': trimmedKey } });
              isValid = r2.ok;
            }
          } catch {
            isValid = false;
          }
        }
        await db.update(userApiKeys)
          .set({ isValid, lastValidated: new Date() })
          .where(and(eq(userApiKeys.userId, req.user!.id), eq(userApiKeys.provider, provider)));
      } catch { /* validation failed — key stays null until explicitly validated */ }

      res.json({ ...sanitizeKeyForResponse(result), isValid, validated: isValid !== null });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/user-api-keys/validate", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: "Not authenticated" });
    try {
      const { provider } = req.body;
      const key = await storage.getActiveUserApiKey(req.user!.id, provider);
      if (!key) {
        const anyKey = await storage.getUserApiKey(req.user!.id, provider);
        if (!anyKey) return res.status(404).json({ message: "Key not found" });
        return res.status(400).json({ message: "Key is not active. Enable it first.", valid: false, provider });
      }
      const decryptedKey = key.apiKey;

      let isValid = false;
      try {
        if (provider === 'openai') {
          const testClient = new (await import('openai')).default({ apiKey: decryptedKey });
          await testClient.models.list();
          isValid = true;
        } else if (provider === 'anthropic') {
          const resp = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: { 'x-api-key': decryptedKey, 'content-type': 'application/json', 'anthropic-version': '2023-06-01' },
            body: JSON.stringify({ model: 'claude-3-haiku-20240307', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] }),
          });
          isValid = resp.status !== 401 && resp.status !== 403;
        } else if (provider === 'google') {
          const resp = await fetch(`https://generativelanguage.googleapis.com/v1/models?key=${decryptedKey}`);
          isValid = resp.ok;
        } else if (provider === 'groq') {
          const resp = await fetch('https://api.groq.com/openai/v1/models', {
            headers: { 'Authorization': `Bearer ${decryptedKey}` },
          });
          isValid = resp.ok;
        } else if (provider === 'mistral') {
          const resp = await fetch('https://api.mistral.ai/v1/models', {
            headers: { 'Authorization': `Bearer ${decryptedKey}` },
          });
          isValid = resp.ok;
        } else if (provider === 'elevenlabs') {
          try {
            const r = await fetch('https://api.elevenlabs.io/v1/models', { headers: { 'xi-api-key': decryptedKey } });
            isValid = r.ok;
            if (!r.ok && r.status !== 401 && r.status !== 403) {
              const r2 = await fetch('https://api.elevenlabs.io/v1/voices', { headers: { 'xi-api-key': decryptedKey } });
              isValid = r2.ok;
            }
          } catch {
            isValid = false;
          }
        }
      } catch (e) {
        isValid = false;
      }

      await db.update(userApiKeys)
        .set({ isValid, lastValidated: new Date() })
        .where(and(eq(userApiKeys.userId, req.user!.id), eq(userApiKeys.provider, provider)));

      res.json({ valid: isValid, provider });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

